CREATE TYPE "ManagedMarketingChannel" AS ENUM ('TIKTOK','FACEBOOK','INSTAGRAM','GOOGLE');
CREATE TYPE "ManagedMarketingExecutionMode" AS ENUM ('MANUAL','AUTOMATED_PROVIDER');
CREATE TYPE "ManagedMarketingPackageStatus" AS ENUM ('DRAFT','ACTIVE','RETIRED');
CREATE TYPE "ManagedMarketingRequestStatus" AS ENUM ('DRAFT','SUBMITTED','APPROVED','REJECTED','SCHEDULED','RUNNING','COMPLETED','CANCELLED');
CREATE TABLE "ManagedMarketingChannelConfiguration" ("id" TEXT NOT NULL,"publicReference" TEXT NOT NULL,"channel" "ManagedMarketingChannel" NOT NULL,"automatedProviderEnabled" BOOLEAN NOT NULL DEFAULT false,"providerConfigurationReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ManagedMarketingChannelConfiguration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ManagedMarketingPackageVersion" ("id" TEXT NOT NULL,"publicReference" TEXT NOT NULL,"code" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"status" "ManagedMarketingPackageStatus" NOT NULL DEFAULT 'DRAFT',"channel" "ManagedMarketingChannel" NOT NULL,"packageTerms" JSONB NOT NULL,"priceAmount" DECIMAL(18,2) NOT NULL,"taxRate" DECIMAL(6,4) NOT NULL,"currency" "LedgerCurrency" NOT NULL DEFAULT 'ZAR',"effectiveAt" TIMESTAMP(3) NOT NULL,"retiredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ManagedMarketingPackageVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ManagedMarketingRequest" ("id" TEXT NOT NULL,"publicReference" TEXT NOT NULL,"storeId" TEXT NOT NULL,"packageVersionId" TEXT NOT NULL,"channel" "ManagedMarketingChannel" NOT NULL,"executionMode" "ManagedMarketingExecutionMode" NOT NULL,"status" "ManagedMarketingRequestStatus" NOT NULL DEFAULT 'DRAFT',"objective" TEXT NOT NULL,"audience" JSONB NOT NULL,"message" TEXT NOT NULL,"destinationLink" TEXT NOT NULL,"creativeAssetReference" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"priceSnapshot" DECIMAL(18,2) NOT NULL,"taxSnapshot" DECIMAL(6,4) NOT NULL,"currency" "LedgerCurrency" NOT NULL DEFAULT 'ZAR',"paymentReference" TEXT,"ledgerJournalId" TEXT,"operationId" TEXT NOT NULL,"requestHash" TEXT NOT NULL,"reviewedByUserId" TEXT,"reviewReason" TEXT,"scheduledAt" TIMESTAMP(3),"runningAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ManagedMarketingRequest_pkey" PRIMARY KEY ("id"),CONSTRAINT "ManagedMarketingRequest_dates" CHECK ("startsAt" < "endsAt"));
CREATE TABLE "ManagedMarketingRequestEvent" ("id" TEXT NOT NULL,"managedMarketingRequestId" TEXT NOT NULL,"operationId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"actorUserId" TEXT,"safeEvidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ManagedMarketingRequestEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ManagedMarketingChannelConfiguration_publicReference_key" ON "ManagedMarketingChannelConfiguration"("publicReference"); CREATE UNIQUE INDEX "ManagedMarketingChannelConfiguration_channel_key" ON "ManagedMarketingChannelConfiguration"("channel"); CREATE UNIQUE INDEX "ManagedMarketingPackageVersion_publicReference_key" ON "ManagedMarketingPackageVersion"("publicReference"); CREATE UNIQUE INDEX "ManagedMarketingPackageVersion_code_versionNumber_key" ON "ManagedMarketingPackageVersion"("code","versionNumber"); CREATE UNIQUE INDEX "ManagedMarketingRequest_publicReference_key" ON "ManagedMarketingRequest"("publicReference"); CREATE UNIQUE INDEX "ManagedMarketingRequest_operationId_key" ON "ManagedMarketingRequest"("operationId"); CREATE INDEX "ManagedMarketingRequest_storeId_status_idx" ON "ManagedMarketingRequest"("storeId","status"); CREATE UNIQUE INDEX "ManagedMarketingRequestEvent_operationId_key" ON "ManagedMarketingRequestEvent"("operationId");
ALTER TABLE "ManagedMarketingRequest" ADD CONSTRAINT "ManagedMarketingRequest_packageVersionId_fkey" FOREIGN KEY ("packageVersionId") REFERENCES "ManagedMarketingPackageVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ManagedMarketingRequestEvent" ADD CONSTRAINT "ManagedMarketingRequestEvent_request_fkey" FOREIGN KEY ("managedMarketingRequestId") REFERENCES "ManagedMarketingRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE OR REPLACE FUNCTION "managed_marketing_package_immutable"() RETURNS trigger AS $$ BEGIN IF OLD.status <> 'DRAFT' THEN RAISE EXCEPTION 'managed marketing package versions are immutable outside DRAFT'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql; CREATE TRIGGER "ManagedMarketingPackageVersion_immutable" BEFORE UPDATE OR DELETE ON "ManagedMarketingPackageVersion" FOR EACH ROW EXECUTE FUNCTION "managed_marketing_package_immutable"();
